"""Randomised replay differential: project agent vs transcribed model.

The generator produces plausible-but-imperfect event streams (stale generations,
reused ids, unregistered names, exhausted marks, tiny capacity limits) and the
driver feeds the recorded wire bytes back into recv events in five variants.
"""
import json, random, sys
sys.path[:0] = ['/workspace/tmp/dev', '/workspace/project', '/opt/emicro-deps']
from model import Model
from ebpf.helper import Agent

POLICIES = [
    'match(A,B) allow;', 'match(A) allow; match(B) allow;', 'startswith(A) allow;',
    'endswith(B) allow;', 'contains(A,B) allow;', 'not(match(A)) allow;',
    '(startswith(A) and endswith(B)) allow;', 'match(A,B) allow; contains(A) drop;',
    'match() allow;', '', '(match(A) or match(B)) allow; match(A,B) drop;',
    'match(A,A) allow; match(B,B) allow; match(A,B) drop;', 'startswith() allow;',
    'not(contains(A)) allow;', 'match(C) allow;', 'match(Z) allow;', 'garbage;',
    'match(A,B,C) allow;' if False else 'match(A,A,A) allow;',
]


def generate(rng, services, limits, count):
    names = [s['name'] for s in services]
    all_names = names + ['Z', 'Q']
    units, conns, files, epochs = [], [], [], []
    unit_serial, conn_serial, file_serial = {}, {}, {}
    rid_serial, stream_serial = {}, {}
    events = []
    for _ in range(count):
        choice = rng.random()
        if choice < .10:
            epoch = rng.choice([1, 2, 3, 5, 8, 13, 4294967294, 4294967295] + [rng.randint(1, 40)])
            events.append({'op': 'stage', 'epoch': epoch, 'policy': rng.choice(POLICIES)})
            epochs.append(epoch)
        elif choice < .14:
            events.append({'op': 'commit', 'epoch': rng.choice(epochs + [1, 2, 99])})
        elif choice < .17:
            events.append({'op': 'retire', 'epoch': rng.choice(epochs + [1, 2, 99])})
        elif choice < .27:
            ns = rng.choice([0, 0, 1, 4294967295])
            pid = rng.choice([1, 2, 3, 7])
            key = (ns, pid)
            gen = unit_serial.get(key, 0) + 1 if rng.random() < .8 else rng.randint(1, 6)
            unit_serial[key] = max(unit_serial.get(key, 0), gen) if rng.random() < .9 else gen
            events.append({'op': 'spawn', 'unit': [ns, pid, gen], 'service': rng.choice(all_names)})
            units.append((ns, pid, gen))
        elif choice < .33:
            if not units:
                continue
            parent = rng.choice(units)
            ns = rng.choice([0, 1, 5])
            pid = rng.choice([1, 2, 9])
            key = (ns, pid)
            gen = unit_serial.get(key, 0) + 1 if rng.random() < .7 else rng.randint(1, 4)
            unit_serial[key] = max(unit_serial.get(key, 0), gen)
            events.append({'op': 'clone', 'parent': list(parent), 'child': [ns, pid, gen]})
            units.append((ns, pid, gen))
        elif choice < .37:
            if not units:
                continue
            events.append({'op': 'exit', 'unit': list(rng.choice(units))})
        elif choice < .47:
            if not units:
                continue
            unit = rng.choice(units)
            key = tuple(unit)
            rid_serial[key] = rid_serial.get(key, 0)
            rid = rid_serial[key] + 1 if rng.random() < .7 else rng.randint(1, 5)
            rid_serial[key] = max(rid_serial.get(key, 0), rid)
            events.append({'op': 'begin', 'unit': list(unit), 'rid': rid})
        elif choice < .52:
            if not units:
                continue
            unit = rng.choice(units)
            key = tuple(unit)
            events.append({'op': 'finish', 'unit': list(unit),
                           'rid': rng.choice([rid_serial.get(key, 1), rid_serial.get(key, 1) - 1, 1, 2])})
        elif choice < .58:
            cid = rng.choice([1, 2, 3, 9])
            gen = conn_serial.get(cid, 0) + 1 if rng.random() < .7 else rng.randint(1, 3)
            conn_serial[cid] = max(conn_serial.get(cid, 0), gen)
            events.append({'op': 'open', 'connection': [cid, gen]})
            conns.append((cid, gen))
        elif choice < .62:
            if not conns:
                continue
            events.append({'op': 'close', 'connection': list(rng.choice(conns))})
        elif choice < .72:
            if not units or not conns:
                continue
            unit = rng.choice(units)
            key = tuple(unit)
            conn = rng.choice(conns)
            ckey = (conn[0], conn[1])
            stream_serial[ckey] = stream_serial.get(ckey, 0)
            stream = stream_serial[ckey] + 1 if rng.random() < .7 else rng.randint(1, 4)
            stream_serial[ckey] = max(stream_serial.get(ckey, 0), stream)
            events.append({'op': 'send', 'unit': list(unit), 'rid': rid_serial.get(key, 1),
                           'connection': list(conn), 'stream': stream,
                           'destination': rng.choice(all_names + ['A'])})
        elif choice < .82:
            if not units or not conns:
                continue
            unit = rng.choice(units)
            conn = rng.choice(conns)
            ckey = (conn[0], conn[1])
            stream = rng.choice([stream_serial.get(ckey, 1), 1, 2, 3])
            events.append({'op': 'recv', 'connection': list(conn), 'stream': stream,
                           'unit': list(unit), 'rid': rng.randint(1, 4),
                           'wire': rng.choice([None, None, '0' * 48, 'X' * 48])})
        elif choice < .88:
            if not units:
                continue
            unit = rng.choice(units)
            key = tuple(unit)
            fid = rng.choice([1, 2, 5])
            gen = file_serial.get(fid, 0) + 1 if rng.random() < .6 else file_serial.get(fid, 1)
            file_serial[fid] = max(file_serial.get(fid, 0), gen)
            events.append({'op': 'store', 'unit': list(unit), 'rid': rid_serial.get(key, 1),
                           'file': [fid, gen]})
            files.append((fid, gen))
        elif choice < .93:
            if not units or not files:
                continue
            fid, gen = rng.choice(files)
            events.append({'op': 'load', 'file': [fid, gen], 'unit': list(rng.choice(units)),
                           'rid': rng.randint(1, 5)})
        elif choice < .96:
            if not files:
                continue
            fid, gen = rng.choice(files)
            events.append({'op': 'unlink', 'file': [fid, gen]})
        else:
            events.append({'op': 'inspect'})
    return events


def invariants(agent, event, position, seed):
    """Recount every resource the agent claims to hold."""
    contexts = 0
    references = {}
    for unit in agent.units.values():
        contexts += len(unit.contexts)
        for epoch, state in unit.contexts.values():
            references[epoch] = references.get(epoch, 0) + 1
            if state != 4294967295 and not 0 <= state < len(agent.images[epoch].rows):
                print('BAD STATE', seed, position, event, epoch, state)
                return False
    packets = 0
    for connection in agent.connections.values():
        packets += len(connection.packets)
        for packet in connection.packets.values():
            references[packet.epoch] = references.get(packet.epoch, 0) + 1
    for _gen, epoch, _state in agent.files.values():
        references[epoch] = references.get(epoch, 0) + 1
    cells = sum(image.cells for image in agent.images.values())
    problems = []
    if contexts != agent.context_count:
        problems.append('contexts %d != %d' % (contexts, agent.context_count))
    if packets != agent.packet_count:
        problems.append('packets %d != %d' % (packets, agent.packet_count))
    if cells != agent._map().cells:
        problems.append('cells %d != %d' % (cells, agent._map().cells))
    if agent._map().cells > agent.limits['cells']:
        problems.append('cells over limit')
    for epoch, image in agent.images.items():
        if image.refs != references.get(epoch, 0):
            problems.append('refs epoch %d: %d != %d' % (epoch, image.refs, references.get(epoch, 0)))
    if agent.active is not None and agent.active not in agent.images:
        problems.append('active not resident')
    if problems:
        print('INVARIANT seed=%d at %d event=%s: %s' %
              (seed, position, json.dumps(event, separators=(',', ':')), '; '.join(problems)))
        return False
    return True


def replay(events, services, limits, seed):
    """Feed recorded wires back into recv events in several variants."""
    agent = Agent(services, limits)
    model = Model(services, limits)
    wires = {}
    delivered = {}
    for position, event in enumerate(events):
        key = (tuple(event['connection']), event['stream'])
        if event['op'] == 'recv' and key in wires:
            real = wires[key]
            variant = (position * 7 + seed) % 6
            if variant == 0:
                event = dict(event, wire=real)
            elif variant == 1:
                event = dict(event, wire=real.upper())
            elif variant == 2:
                event = dict(event, wire=real[:-1] + ('0' if real[-1] != '0' else '1'))
            elif variant == 3:
                event = dict(event, wire=real + ' ')
            elif variant == 4 and key in delivered:
                event = dict(event, rid=delivered[key], wire=real)
            if variant == 4 or (variant == 5 and key in delivered):
                event = dict(event, unit=list(delivered[key + 'unit'])) if key + 'unit' in delivered else event
        got = agent.event(event)
        want = model.do(event)
        if not invariants(agent, event, position, seed):
            return False
        if got != want:
            print('MISMATCH seed=%d at %d event=%s\n   got=%s\n  want=%s' %
                  (seed, position, json.dumps(event, separators=(',', ':')),
                   json.dumps(got, separators=(',', ':')), json.dumps(want, separators=(',', ':'))))
            print('   services=%s limits=%s' % (services, limits))
            return False
        if event['op'] == 'send' and got.get('ok'):
            wires[key] = got['wire']
        if event['op'] == 'recv' and got.get('ok'):
            delivered[key] = event['rid']
            delivered[key + 'unit'] = event['unit']
    return True


def run(seed):
    rng = random.Random(seed)
    size = rng.randint(1, 4)
    names = [chr(ord('A') + i) for i in range(size)]
    labels = rng.sample(range(1, 50), size)
    services = [{'name': n, 'label': l} for n, l in zip(names, labels)]
    rng.shuffle(services)
    if rng.random() < .4:
        limits = {'images': rng.randint(1, 3), 'cells': rng.choice([1, 2, 5, 20, 262144]),
                  'units': rng.randint(1, 4), 'contexts': rng.randint(1, 6),
                  'connections': rng.randint(1, 3), 'packets': rng.randint(1, 4),
                  'files': rng.randint(1, 3)}
    else:
        limits = {'images': 16, 'cells': 262144, 'units': 1024, 'contexts': 32768,
                  'connections': 4096, 'packets': 32768, 'files': 8192}
    events = generate(rng, services, limits, rng.randint(1, 220))
    return replay(events, services, limits, seed)


def main():
    rounds = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
    start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    failures = 0
    for seed in range(start, start + rounds):
        if not run(seed):
            failures += 1
            if failures > 6:
                break
    print('replay fuzz rounds=%d failures=%d' % (rounds, failures))


if __name__ == '__main__':
    main()
